UPDATE project SET pitch = '{"fr": "Une application personnelle pour organiser vie pro et vie perso dans un agenda complet : sport, dépenses, tâches, rendez-vous."}', stack = '["Angular 22", "Java 21", "Spring Boot 4.1", "MySQL", "Docker Compose"]', duration = '{"fr": "En cours"}',
    role = '{"fr": "Conception et développement, seul et de zéro : backend, frontend, et la mise en place de Spring Boot et d''Angular"}', problem = '{"fr": "Mon quotidien était éparpillé : les sorties dans Garmin, les dépenses d''un côté, les tâches et les rendez-vous de l''autre. Je voulais tout voir au même endroit, avec mes activités sportives dedans."}', decisions = '{"fr": [{"title": "Garmin dans un service séparé", "tradeoff": "Garmin n''offre pas d''accès officiel : j''utilise une bibliothèque non officielle, que j''ai isolée du backend. Un service de plus à lancer et à protéger, mais une dépendance fragile qui ne contamine pas le reste. Et quand Garmin refuse la connexion, l''erreur réelle remonte jusqu''à l''écran au lieu d''un message vague."}, {"title": "Gemini plutôt qu''Anthropic pour le coach IA", "tradeoff": "Gemini propose un tier gratuit, pas l''API Anthropic : pour un projet personnel, le choix était vite fait. Contrepartie : le coach reste muet sans clé, et le nom du modèle a déjà demandé une correction."}, {"title": "Verrouillage de connexion par e-mail et par IP", "tradeoff": "Un inconnu ne peut pas bloquer mon compte depuis sa propre machine. Contrepartie : le compteur vit en mémoire, il repart à zéro au redémarrage et ne se partage pas entre plusieurs instances."}]}',
    wall = '{"fr": "Le plus dur n''était pas le code : c''était de synthétiser mon idée et de lui donner forme. Passer d''un besoin flou, organiser ma vie pro et perso, à un produit concret."}', takeaway = '{"fr": "Dépendre d''une API non officielle, c''est prévoir dès le départ où elle casse, et le dire clairement à l''utilisateur."}', ai_note = '{"fr": "Commencé à la main, puis poursuivi avec l''aide de l''IA."}'
WHERE slug = 'oltre';
UPDATE project SET pitch = '{"fr": "Le suivi GPS en direct d''une course à pied : mes proches me suivent sur une carte, sans rien installer."}', stack = '["Node.js 22", "JavaScript natif", "Leaflet", "Docker Compose", "Caddy"]', duration = '{"fr": "Depuis octobre 2026"}',
    role = '{"fr": "Conception et développement"}', problem = '{"fr": "Zotracker est né pour le marathon de Lille : mes parents, ma famille et mes amis voulaient me suivre en direct. Il fonctionne dans le navigateur, sans appli à installer, et je compte le réutiliser sur d''autres courses."}', decisions = '{"fr": [{"title": "Des fichiers JSON plutôt qu''une base de données", "tradeoff": "Aucun service à lancer ni à sauvegarder. Contrepartie : les écritures sur disque sont à ma charge. J''ai déjà ajouté un nouvel essai en cas d''échec et un refus de démarrer si le fichier est corrompu."}, {"title": "Un front en JavaScript natif, sans bundler", "tradeoff": "Aucune étape de build. Contrepartie : du code dupliqué entre serveur et navigateur. Les statistiques sont calculées deux fois, et les deux résultats divergent déjà sur l''heure d''arrivée estimée avant le départ."}, {"title": "Distance calculée sur le tracé GPX", "tradeoff": "La distance suit le parcours officiel, sans le zigzag du GPS. Les points à plus de 100 m sont ignorés, et un écart de plus de 150 m affiche « hors parcours ». Sans fichier GPX, le serveur retombe sur les points bruts, moins précis."}]}',
    wall = '{"fr": "Le jour de la course, tout peut lâcher : le réseau se coupe, le GPS du navigateur s''éteint quand l''écran se verrouille (sur iPhone), les alertes de sécurité doivent partir quand même. Les points sont mis en attente quand le réseau tombe ; le reste de cette fiabilité est encore à construire."}', takeaway = '{"fr": "Une appli utilisée le jour J ne se juge pas à sa démo : elle se juge au pire moment de la course. D''où le mode simulation, pour tester sans courir."}', ai_note = '{"fr": "Conçu avec IA."}'
WHERE slug = 'zotracker';
UPDATE project SET pitch = '{"fr": "Un planificateur de repas pour une famille, mon projet de fin d''études."}', stack = '["Java 21", "Quarkus", "PostgreSQL", "Docker Compose", "OpenAPI"]', duration = '{"fr": "Janvier à mars 2025"}',
    role = '{"fr": "Équipe de quatre. Je me suis occupé du front et du back."}', problem = '{"fr": "Un professeur voulait un planificateur de repas pour sa famille. Le cahier des charges de départ était imposé : il fallait le respecter. Ensuite, la liberté d''innover au-delà."}', decisions = '{"fr": [{"title": "Des jetons signés en RSA", "tradeoff": "La signature se vérifie avec une clé publique, la clé privée reste à l''abri. Contrepartie : générer et distribuer les clés se fait à la main."}, {"title": "Un certificat dédié pour l''API Spoonacular", "tradeoff": "La connexion HTTPS passe par un certificat importé à la main. Contrepartie : une étape manuelle à refaire sur chaque machine."}]}',
    wall = '{"fr": "Faire converger les idées de quatre personnes, et tenir les délais de livraison."}', takeaway = '{"fr": "Un bon résultat, et une bonne expérience d''équipe."}', ai_note = NULL
WHERE slug = 'gfaim';
UPDATE project SET pitch = '{"fr": "Pendant 2,5 ans, j''ai fait évoluer une application qui permet à des professionnels de la finance d''acheter et de vendre des titres en bourse."}', stack = '["Java", "Spring Boot", "JEE", "Hibernate", "REST", "messaging asynchrone", "GitLab CI", "Docker"]', duration = '{"fr": "2,5 ans d''expérience professionnelle (mars 2023 à septembre 2025)"}',
    role = '{"fr": "Développeur back-end, puis fullstack"}', problem = '{"fr": "Une application de trading n''a pas droit à l''approximation. Quand on achète ou qu''on vend des titres, une erreur ne reste pas dans un fichier de log : elle se voit dans un ordre. Mon travail : livrer des évolutions complètes, de l''analyse du besoin à la mise en production, en équipe Scrum."}', decisions = '{"fr": [{"title": "Tester en conditions réelles", "tradeoff": "Une date codée en dur a masqué un bug jusqu''en production. Depuis, je teste dans des conditions proches du réel, ce qui demande plus de temps de préparation avant la livraison."}, {"title": "Valider la maquette avant de coder", "tradeoff": "Sur une fonctionnalité portée seul, en dernière année, j''ai fait valider la maquette par le Product Owner avant le développement. Un échange de plus au départ, mais moins de retours en cours de route."}]}',
    wall = '{"fr": "La complexité de la solution, et le respect de la Definition of Done : une évolution n''est terminée que lorsque tout est vérifié, testé et relu."}', takeaway = '{"fr": "Travailler sur un système critique m''a appris la rigueur : analyser avant de coder, tester avant de livrer, et garder la tête froide quand tout va vite."}', ai_note = NULL
WHERE slug = 'trading-app';
